// DOM integration, synthetic account/market only. No production identity or financial state.
const {JSDOM,VirtualConsole}=require(process.env.COCO_JSDOM_PATH||'jsdom'),assert=require('node:assert/strict');
(async()=>{const {renderApp}=await import('../src/ui.mjs'),{action,summary,CATALOG}=await import('../src/engine.mjs');const now=Date.now(),market={prices:Object.fromEntries(CATALOG.map(c=>[c.id,{eur:100,local:110,currency:'USD',at:now-86400000,fetchedAt:now}])),rate:{annualPct:2.4,date:new Date(now-86400000).toISOString().slice(0,10),fetchedAt:now},events:[],updatedAt:now};let state=null,configured=false,errors=[],requests=[];const payload=()=>({state,summary:state?.config?summary(state,market,now):null,market,catalog:CATALOG,serverTime:now,parent:{configured}});const vc=new VirtualConsole();vc.on('jsdomError',e=>{if(!e.message.includes('scrollTo'))errors.push(e.message)});const dom=new JSDOM(renderApp(),{url:'https://bank.test/',runScripts:'dangerously',virtualConsole:vc,beforeParse(w){w.scrollTo=()=>{};w.structuredClone=structuredClone;w.parent.postMessage=msg=>{requests.push(msg);if(!msg.path)return;queueMicrotask(()=>{let data,error;try{if(msg.path==='/state')data=payload();else if(msg.body.type==='parent_unlock'||msg.body.type==='parent_set_pin'){configured=true;data={token:'x'.repeat(64),expires:Date.now()+300000}}else if(msg.body.type==='parent_lock')data={locked:true};else{state=action(state,market,msg.body,now,{parent:true});data=payload()}}catch(e){error=e.message}w.dispatchEvent(new w.MessageEvent('message',{source:w.parent,data:{reply:true,channel:msg.channel,id:msg.id,data,error}}))})}}});const w=dom.window,doc=w.document,tick=()=>new Promise(r=>setTimeout(r,10)),click=async sel=>{assert.ok(doc.querySelector(sel),'missing '+sel);doc.querySelector(sel).click();await tick()},form=async(id,values)=>{const f=doc.getElementById(id);assert.ok(f,'missing form '+id);for(const [k,v]of Object.entries(values))f.elements.namedItem(k).value=String(v);f.dispatchEvent(new w.Event('submit',{bubbles:true,cancelable:true}));await tick()};await tick();await form('account',{name:'Test <child>'});await click('[data-parent]');await form('pin',{password:'test-only',pin:'123456',repeat:'123456'});assert.ok(doc.getElementById('setup'));await form('setup',{salary:100,initial:20});await click('[data-receive]');assert.equal(state.cash,12000);assert.equal(state.bills.length,0);await click('[data-go="invest"]');assert.equal(doc.querySelectorAll('[data-asset]').length,20);await click('[data-asset="NVDA"]');await click('[data-lesson="NVDA"]');await click('[data-answer="NVDA:risk"]');await form('trade',{amount:10,reason:'Quiero aprender sobre chips y sus riesgos.'});assert.equal(state.orders.length,1);assert.equal(state.orders[0].amount,1000);await click('[data-go="portfolio"]');await click('[data-cancel]');assert.equal(state.orders.length,0);await click('[data-go="invest"]');await click('[data-group="deposit"]');await click('[data-lesson="DEPOSIT"]');await click('[data-answer="DEPOSIT:locked"]');await form('trade',{amount:10,term:30,reason:'Quiero aprender a esperar hasta el vencimiento.'});assert.equal(state.deposits.length,1);await click('[data-go="learn"]');await click('[data-go="lab"]');const before=structuredClone(state);await form('compound',{initial:100,monthly:0,years:2,annualPct:5});assert.deepEqual(state,before);await click('[data-back]');assert.match(doc.getElementById('content').textContent,/La bolsa/);await click('[data-close]');assert.equal(requests.at(-1).close,true);assert.deepEqual(errors,[]);console.log('PASS: onboarding, PIN, allowance, 20-company catalogue, quiz, buy/cancel, deposit, compound lab, back and exit using synthetic state.');dom.window.close();})().catch(e=>{console.error(e);process.exit(1)});
